/**
 * The private subject "Aptitudini Aviație — Set extins" (Rareș only, + his guardians as watchers),
 * filled with ORIGINAL exercises generated by scripts/lib/aptitudini-extins-gen.mjs: number series
 * and numerical reasoning on airline figures — the cut-e/COMPASS formats his current subject lacks.
 *
 * Every row is marked in `sourceReference` ("aptitudini-ext-gen:<tip>:<regulă>"), so it is always
 * clear where it came from. Re-running only ADDS the items not already there — it never deletes:
 * deleting a question would take its answers with it (cascade), i.e. Rareș's practice history.
 *
 * Probe (writes nothing):  node scripts/seed-aptitudini-extins.mjs
 * Write:                   node scripts/seed-aptitudini-extins.mjs --apply
 * (on the VPS: cd /var/www/tutor && node --env-file=.env scripts/seed-aptitudini-extins.mjs --apply)
 */
import { PrismaClient } from "@prisma/client";
import { genNumerical, genSeries, rng, validateItem } from "./lib/aptitudini-extins-gen.mjs";

const prisma = new PrismaClient();
const SLUG = "aptitudini-aviatie-extins";
const NAME = "Aptitudini Aviație — Set extins";
// STUDENT_EMAIL can be overridden to try the script on the QA database.
const STUDENT_EMAIL = process.env.STUDENT_EMAIL || "raresdanciulescu9@gmail.com";
const PER_KIND = 250;
const apply = process.argv.includes("--apply");

async function main() {
  const seed = Number(process.env.SEED) || Date.now() % 2 ** 31;
  const rand = rng(seed);
  // Generate until PER_KIND DISTINCT items of each kind (a repeat is no extra practice), with a cap:
  // the numerical space is finite, and the cap stops a kind that cannot reach the target.
  const collect = (gen) => {
    const byText = new Map();
    for (let tries = 0; byText.size < PER_KIND && tries < PER_KIND * 40; tries++) {
      const q = gen(rand);
      if (!byText.has(q.content)) byText.set(q.content, q);
    }
    return [...byText.values()];
  };
  const rows = [...collect(genSeries), ...collect(genNumerical)];
  const bad = rows.map((q) => [q, validateItem(q)]).filter(([, why]) => why);
  if (bad.length) {
    console.error("Exerciții invalide, nu scriu nimic:", bad.slice(0, 5));
    process.exit(1);
  }
  const unique = rows;
  console.log(`${unique.length} exerciții unice (sămânța ${seed}): ${unique.filter((q) => q.ref.includes(":serii:")).length} serii, ${unique.filter((q) => q.ref.includes(":numeric:")).length} numerice.`);
  for (const q of unique.slice(0, 2).concat(unique.slice(-2))) console.log(`  — ${q.content.replace(/\n/g, " ")} | ${q.options.join(" / ")} | corect: ${q.correctAnswer}`);

  const student = await prisma.user.findUnique({ where: { email: STUDENT_EMAIL }, select: { id: true } });
  if (!student) throw new Error(`Elevul nu există: ${STUDENT_EMAIL}`);
  const guardians = await prisma.guardian.findMany({ where: { childId: student.id, status: "active" }, select: { parentId: true } });
  console.log(`Elev: ${student.id}; părinți (observatori): ${guardians.length}.`);
  if (!apply) {
    console.log("\nProbă — nu scriu nimic. Rulează cu --apply.");
    return;
  }

  const domain = await prisma.domain.upsert({
    where: { slug: SLUG },
    create: {
      name: NAME,
      slug: SLUG,
      description:
        "Exerciții originale generate de eTutor în formatele testelor de selecție piloți (cut-e / COMPASS): serii de numere și raționament numeric pe date de zbor.",
      icon: "✈️",
      isActive: true,
      visibility: "PRIVATE",
    },
    update: {},
  });

  await prisma.enrollment.upsert({
    where: { userId_domainId: { userId: student.id, domainId: domain.id } },
    create: { userId: student.id, domainId: domain.id, roles: ["STUDENT"], isActive: true },
    update: { isActive: true },
  });
  for (const g of guardians) {
    await prisma.enrollment.upsert({
      where: { userId_domainId: { userId: g.parentId, domainId: domain.id } },
      create: { userId: g.parentId, domainId: domain.id, roles: ["WATCHER"], isActive: true },
      update: { isActive: true },
    });
  }

  const existing = new Set(
    (await prisma.question.findMany({ where: { domainId: domain.id }, select: { content: true } })).map((q) => q.content)
  );
  const fresh = unique.filter((q) => !existing.has(q.content));
  const offset = existing.size;
  const created = await prisma.question.createMany({
    data: fresh.map((q, idx) => ({
      domainId: domain.id,
      subject: q.subject,
      topic: q.topic,
      difficulty: q.difficulty,
      type: "MULTIPLE_CHOICE",
      content: q.content,
      options: q.options,
      correctAnswer: q.correctAnswer,
      explanation: q.explanation,
      source: "MANUAL",
      status: "PUBLISHED",
      sourceReference: q.ref,
      bookOrder: offset + idx,
    })),
  });
  console.log(`\nMaterie: ${NAME} (${SLUG}, ${domain.id}). Existau ${existing.size}, adăugate ${created.count}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
